inline constexpr size_t kLuaBindingCount = 427;
inline constexpr size_t kLuaBindingCountBase = 30;
inline constexpr size_t kLuaBindingCountMc = 30;
inline constexpr size_t kLuaBindingCountMission = 189;
inline constexpr size_t kLuaBindingCountOther = 50;
inline constexpr size_t kLuaBindingCountStdlib = 128;
inline constexpr size_t kLuaBindingTypedCount = 46;

constexpr bool SwLuaTableEquals(const char* a, const char* b) {
    if (!a || !b) return false;
    while (*a && *a == *b) { ++a; ++b; }
    return *a == *b;
}

constexpr size_t SwLuaCountTable(const char* table) {
    size_t count = 0;
    for (size_t i = 0; i < kLuaBindingCount; ++i)
        if (SwLuaTableEquals(kLuaBindings[i].table, table)) ++count;
    return count;
}

constexpr size_t SwLuaCountTyped() {
    size_t count = 0;
    for (size_t i = 0; i < kLuaBindingCount; ++i)
        if (kLuaBindings[i].arity >= 0) ++count;
    return count;
}

static_assert(sizeof(kLuaBindings) / sizeof(kLuaBindings[0]) == kLuaBindingCount,
              "kLuaBindings size does not match kLuaBindingCount");
static_assert(SwLuaCountTable("base") == kLuaBindingCountBase,
              "table count mismatch: base");
static_assert(SwLuaCountTable("mc") == kLuaBindingCountMc,
              "table count mismatch: mc");
static_assert(SwLuaCountTable("mission") == kLuaBindingCountMission,
              "table count mismatch: mission");
static_assert(SwLuaCountTable("other") == kLuaBindingCountOther,
              "table count mismatch: other");
static_assert(SwLuaCountTable("stdlib") == kLuaBindingCountStdlib,
              "table count mismatch: stdlib");
static_assert(SwLuaCountTyped() == kLuaBindingTypedCount,
              "typed binding count mismatch");
